export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-19\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 19,\n    \"title\": \"難二\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 11,\n    \"passageIds\": [\n      \"han-fei-zi_ch-19_p-1\",\n      \"han-fei-zi_ch-19_p-2\",\n      \"han-fei-zi_ch-19_p-3\",\n      \"han-fei-zi_ch-19_p-4\",\n      \"han-fei-zi_ch-19_p-5\",\n      \"han-fei-zi_ch-19_p-6\",\n      \"han-fei-zi_ch-19_p-7\",\n      \"han-fei-zi_ch-19_p-8\",\n      \"han-fei-zi_ch-19_p-9\",\n      \"han-fei-zi_ch-19_p-10\",\n      \"han-fei-zi_ch-19_p-11\",\n      \"han-fei-zi_ch-19_p-12\",\n      \"han-fei-zi_ch-19_p-13\",\n      \"han-fei-zi_ch-19_p-14\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 1,\n      \"canonicalText\": \"景公過晏子曰：「子宮小，近市，請徙子家豫章之圃。」晏子再拜而辭曰：「且嬰家貧，待市食，而朝暮趨之，不可以遠。」景公笑曰：「子家習市，識貴賤乎？」是時景公繁於刑，晏子對曰：「踴貴而屨賤。」景公曰：「何故？」對曰：「刑多也。」景公造然變色曰：「寡人其暴乎！」於是損刑五。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-1_s-1\",\n        \"han-fei-zi_ch-19_p-1_s-2\",\n        \"han-fei-zi_ch-19_p-1_s-3\",\n        \"han-fei-zi_ch-19_p-1_s-4\",\n        \"han-fei-zi_ch-19_p-1_s-5\",\n        \"han-fei-zi_ch-19_p-1_s-6\",\n        \"han-fei-zi_ch-19_p-1_s-7\",\n        \"han-fei-zi_ch-19_p-1_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"景公過晏子說道：子宮小，近市，請徙子家豫章的圃。晏子再拜而且辭說道：且嬰家貧，待市食，而且朝暮趨的，不可以遠。景公笑說道：子家習市，識貴賤乎？是時景公繁於刑，晏子對說道：踴貴而且屨賤。景公說道：何所以？對說道：刑多啊。景公造然變色說道：寡人他的暴乎！於是損刑五。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「景公過晏子曰：「子宮小，近市，請徙子家豫章之圃」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「景」、「公」、「過」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「景公過晏子曰子宮小近市請徙子家豫章之圃晏子再拜而」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」晏子再拜而辭曰：「且嬰家貧，待市食，而朝暮趨之，不可以遠」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 2,\n      \"canonicalText\": \"或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也。夫刑當無多，不當無少，無以不當聞，而以太多說，無術之患也。敗軍之誅以千百數，猶北不止。即治亂之刑如恐不勝，而姦尚不盡。今晏子不察其當否，而以太多為說，不亦妄乎！夫惜草茅者耗禾穗，惠盜賊者傷良民。今緩刑罰，行寬惠，是利姦邪而害善人也，此非所以為治也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-2_s-1\",\n        \"han-fei-zi_ch-19_p-2_s-2\",\n        \"han-fei-zi_ch-19_p-2_s-3\",\n        \"han-fei-zi_ch-19_p-2_s-4\",\n        \"han-fei-zi_ch-19_p-2_s-5\",\n        \"han-fei-zi_ch-19_p-2_s-6\",\n        \"han-fei-zi_ch-19_p-2_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：晏子的貴踴，絕不是他的誠啊，欲便辭以止多刑啊，此不察治的患啊。夫刑當無多，不當無少，無以不當聞，而且以太多說，無督察權術的患啊。敗軍的誅以千百數，猶北不止。即治亂的刑如恐不勝，而且姦尚不盡。今晏子不察他的當否，而且以太多為說，不亦妄乎！夫惜草茅的人或事耗禾穗，惠盜賊的人或事傷良民。今緩刑刑罰，行寬惠，是利姦邪而且害善人啊，此絕不是所以為治啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「晏」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰晏子之貴踴非其誠也欲便辭以止多刑也此不察治之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫刑當無多，不當無少，無以不當聞，而以太多說，無術之患也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 3,\n      \"canonicalText\": \"齊桓公飲酒醉，遺其冠，恥之，三日不朝。管仲曰：「此非有國之恥也，公胡其不雪之以政？」公曰：「胡其善。」因發倉囷，賜貧窮；論囹圄，出薄惱。處三日而民歌之曰：「公胡不復遺冠乎！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-3_s-1\",\n        \"han-fei-zi_ch-19_p-3_s-2\",\n        \"han-fei-zi_ch-19_p-3_s-3\",\n        \"han-fei-zi_ch-19_p-3_s-4\",\n        \"han-fei-zi_ch-19_p-3_s-5\",\n        \"han-fei-zi_ch-19_p-3_s-6\",\n        \"han-fei-zi_ch-19_p-3_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公飲酒醉，遺他的冠，恥的，三日不朝。管仲說道：此絕不是有國的恥啊，公胡他的不雪的以政？公說道：胡他的善。因發倉囷，賜貧窮；論囹圄，出薄惱。處三日而且民歌的說道：公胡不復遺冠乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「齊桓公飲酒醉，遺其冠，恥之，三日不朝」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊桓公飲酒醉遺其冠恥之三日不朝管仲曰此非有國之恥」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「管仲曰：「此非有國之恥也，公胡其不雪之以政」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 4,\n      \"canonicalText\": \"或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣。使桓公發倉囷而賜貧窮，論囹圄而出薄惱，非義也，不可以雪恥使之而義也。桓公宿義，須遺冠而後行之，則是桓公行義，非為遺冠也。是雖雪遺冠之恥於小人，而亦遺義之恥於君子矣。且夫發囷倉而賜貧窮者，是賞無功也；論囹圄而出薄惱者，是不誅過也。夫賞無功則民偷幸而望於上，不誅過則民不懲而易為非，此亂之本也，安可以雪恥哉？\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-4_s-1\",\n        \"han-fei-zi_ch-19_p-4_s-2\",\n        \"han-fei-zi_ch-19_p-4_s-3\",\n        \"han-fei-zi_ch-19_p-4_s-4\",\n        \"han-fei-zi_ch-19_p-4_s-5\",\n        \"han-fei-zi_ch-19_p-4_s-6\",\n        \"han-fei-zi_ch-19_p-4_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：管仲雪桓公的恥於小人，而且生桓公的恥於國君子矣。使桓公發倉囷而且賜貧窮，論囹圄而且出薄惱，絕不是義啊，不可以雪恥使的而且義啊。桓公宿義，須遺冠而且後行的，則是桓公行義，絕不是為遺冠啊。是雖雪遺冠的恥於小人，而且亦遺義的恥於國君子矣。再的人或事況且發囷倉而且賜貧窮的人或事，是賞賜無功啊；論囹圄而且出薄惱的人或事，是不誅過啊。夫賞賜無功則民偷幸而且望於上，不誅過則民不懲而且易為絕不是，此亂的本啊，安可以雪恥哉？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「管」、「仲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰管仲雪桓公之恥於小人而生桓公之恥於君子矣使桓」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「使桓公發倉囷而賜貧窮，論囹圄而出薄惱，非義也，不可以雪恥使之而義也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 5,\n      \"canonicalText\": \"昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說。仲尼聞之曰：「仁哉文王！輕千里之國而請解炮烙之刑。智哉文王！出千里之地而得天下之心。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-5_s-1\",\n        \"han-fei-zi_ch-19_p-5_s-2\",\n        \"han-fei-zi_ch-19_p-5_s-3\",\n        \"han-fei-zi_ch-19_p-5_s-4\",\n        \"han-fei-zi_ch-19_p-5_s-5\",\n        \"han-fei-zi_ch-19_p-5_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"昔的人或事文王侵孟、克莒、舉酆，三舉事而且紂惡的，文王乃懼，請入洛西的地、赤壤的國、方千里以請解炮烙的刑，天下皆說。仲尼聞的說道：仁哉文王！輕千里的國而且請解炮烙的刑。智哉文王！出千里的地而且得天下的心。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「昔」、「文」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「昔者文王侵孟克莒舉酆三舉事而紂惡之文王乃懼請入洛」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「仲尼聞之曰：「仁哉文王」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 6,\n      \"canonicalText\": \"或曰：仲尼以文王為智也，不亦過乎！夫智者知禍難之地而闢之者也，是以身不及於患也。使文王所以見惡於紂者，以其不得人心耶？則雖索人心以解惡可也。紂以其大得人心而惡之，己又輕地以收人心，是重見疑也。固其所以桎梏囚於羑里也。鄭長者有言：「體道，無為、無見也。」此最宜於文王矣，不使人疑之也。仲尼以文王為智，未及此論也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-6_s-1\",\n        \"han-fei-zi_ch-19_p-6_s-2\",\n        \"han-fei-zi_ch-19_p-6_s-3\",\n        \"han-fei-zi_ch-19_p-6_s-4\",\n        \"han-fei-zi_ch-19_p-6_s-5\",\n        \"han-fei-zi_ch-19_p-6_s-6\",\n        \"han-fei-zi_ch-19_p-6_s-7\",\n        \"han-fei-zi_ch-19_p-6_s-8\",\n        \"han-fei-zi_ch-19_p-6_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：仲尼以文王為智啊，不亦過乎！夫智的人或事知禍難的地而且闢的的人或事啊，是以身不及於患啊。使文王所以見惡於紂的人或事，以他的不得人心耶？則雖索人心以解惡可啊。紂以他的大得人心而且惡的，己又輕地以收人心，是重見疑啊。固他的所以桎梏囚於羑里啊。鄭長的人或事有言：體道，無為、無見啊。此最宜於文王矣，不使人疑的啊。仲尼以文王為智，未及此論啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：仲尼以文王為智也，不亦過乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「仲」、「尼」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰仲尼以文王為智也不亦過乎夫智者知禍難之地而闢」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫智者知禍難之地而闢之者也，是以身不及於患也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 7,\n      \"canonicalText\": \"晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也？君之力也？」叔向對曰：「管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，君舉而服之，亦臣之力也，君何力之有？」師曠伏琴而笑之。公曰：「太師奚笑也？」師曠對曰：「臣笑叔向之對君也。凡為人臣者，猶炮宰和五味而進之君，君弗食，孰敢強之也。臣請譬之：君者、壤地也，臣者、草木也，必壤地美然後草木碩大，亦君之力也，臣何力之有？」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-7_s-1\",\n        \"han-fei-zi_ch-19_p-7_s-2\",\n        \"han-fei-zi_ch-19_p-7_s-3\",\n        \"han-fei-zi_ch-19_p-7_s-4\",\n        \"han-fei-zi_ch-19_p-7_s-5\",\n        \"han-fei-zi_ch-19_p-7_s-6\",\n        \"han-fei-zi_ch-19_p-7_s-7\",\n        \"han-fei-zi_ch-19_p-7_s-8\",\n        \"han-fei-zi_ch-19_p-7_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"晉平公問叔向說道：昔的人或事齊桓公九合諸侯，一匡天下，不識臣屬的力啊？國君的力啊？叔向對說道：管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，國君舉而且服的，亦臣屬的力啊，國君何力的有？師曠伏琴而且笑的。公說道：太師奚笑啊？師曠對說道：臣屬笑叔向的對國君啊。凡為人臣屬的人或事，猶炮宰和五味而且進的國君，國君弗食，孰敢強的啊。臣屬請譬的：國君的人或事、壤地啊，臣屬的人或事、草木啊，必壤地美然後草木碩大，亦國君的力啊，臣屬何力的有？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「晉」、「平」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「晉平公問叔向曰昔者齊桓公九合諸侯一匡天下不識臣之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「君之力也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 8,\n      \"canonicalText\": \"或曰：叔向、師曠之對皆偏辭也。夫一匡天下，九合諸侯，美之大者也，非專君之力也，又非專臣之力也。昔者宮之奇在虞，僖負眾在曹，二臣之智，言中事，發中功，虞、曹俱亡者何也？此有其臣而無其君者也。且蹇叔處幹而幹亡，處秦而秦霸，非蹇叔愚於幹而智於秦也，此有君與無臣也。向曰「臣之力也」不然矣。昔者桓公宮中二市，婦閭二百，被髮而御婦人，得管仲為五伯長，失管仲得豎刁，而身死，蟲流出屍不葬。以為非臣之力也，且不以管仲為霸；以為君之力也，且不以豎刁為亂。昔者晉文公慕於齊女而亡歸，咎犯極諫，故使反晉國。故桓公以管仲合，文公以舅犯霸，而師曠曰「君之力也」又不然矣。凡五霸所以能成功名於天下者，必君臣俱有力焉。故曰：叔向、師曠之對皆偏辭也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-8_s-1\",\n        \"han-fei-zi_ch-19_p-8_s-2\",\n        \"han-fei-zi_ch-19_p-8_s-3\",\n        \"han-fei-zi_ch-19_p-8_s-4\",\n        \"han-fei-zi_ch-19_p-8_s-5\",\n        \"han-fei-zi_ch-19_p-8_s-6\",\n        \"han-fei-zi_ch-19_p-8_s-7\",\n        \"han-fei-zi_ch-19_p-8_s-8\",\n        \"han-fei-zi_ch-19_p-8_s-9\",\n        \"han-fei-zi_ch-19_p-8_s-10\",\n        \"han-fei-zi_ch-19_p-8_s-11\",\n        \"han-fei-zi_ch-19_p-8_s-12\",\n        \"han-fei-zi_ch-19_p-8_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：叔向、師曠的對皆偏辭啊。夫一匡天下，九合諸侯，美的大的人或事啊，絕不是專國君的力啊，又絕不是專臣屬的力啊。昔的人或事宮的奇在虞，僖負眾在曹，二臣屬的智，言中事，發中功，虞、曹俱亡的人或事何啊？此有他的臣屬而且無他的國君的人或事啊。且蹇叔處幹而且幹亡，處秦而且秦霸，絕不是蹇叔愚於幹而且智於秦啊，此有國君與無臣屬啊。向說道：臣屬的力啊不然矣。昔的人或事桓公宮中二市，婦閭二百，被髮而且御婦人，得管仲為五伯長，失管仲得豎刁，而且身死，蟲流出屍不葬。以為絕不是臣屬的力啊，且不以管仲為霸；以為國君的力啊，且不以豎刁為亂。昔的人或事晉文公慕於齊女而且亡歸，咎犯極諫，所以使反晉國。所以桓公以管仲合，文公以舅犯霸，而且師曠說道：國君的力啊又不然矣。凡五霸所以能成功名於天下的人或事，必國君臣屬俱有力焉。因此韓絕不是子評論說道：叔向、師曠的對皆偏辭啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：叔向、師曠之對皆偏辭也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「叔」、「向」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰叔向師曠之對皆偏辭也夫一匡天下九合諸侯美之大」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫一匡天下，九合諸侯，美之大者也，非專君之力也，又非專臣之力也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 9,\n      \"canonicalText\": \"齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。而優笑曰：「易哉為君，一曰仲父，二曰仲父。」桓公曰：「吾聞君人者勞於索人，佚於使人。吾得仲父已難矣，得仲父之後，何為不易乎哉！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-9_s-1\",\n        \"han-fei-zi_ch-19_p-9_s-2\",\n        \"han-fei-zi_ch-19_p-9_s-3\",\n        \"han-fei-zi_ch-19_p-9_s-4\",\n        \"han-fei-zi_ch-19_p-9_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公的時，晉客至，有司請禮，桓公說道：告仲父的人或事三。而且優笑說道：易哉為國君，一說道：仲父，二說道：仲父。桓公說道：吾聞國君人的人或事勞於索人，佚於使人。吾得仲父已難矣，得仲父的後，何為不易乎哉！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊桓公之時晉客至有司請禮桓公曰告仲父者三而優笑曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「而優笑曰：「易哉為君，一曰仲父，二曰仲父」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 10,\n      \"canonicalText\": \"或曰：桓公之所應優，非君人者之言也。桓公以君人為勞於索人，何索人為勞哉？伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱也，宰所羞也，蒙羞辱而接君上，賢者之憂世急也；然則君人者無道賢而已矣，索賢不為人主難。且官職所以任賢也，爵祿所以賞功也，設官職，陳爵祿，而士自至，君人者奚其勞哉！使人又非所佚也，人主雖使人必以度量準之，以刑名參之，以事；遇於法則行，不遇於法則止；功當其言則賞，不當則誅；以刑名收臣，以度量準下；此不可釋也，君人者焉佚哉？索人不勞，使人不佚，而桓公曰「勞於索人，佚於使人」者，不然。且桓公得管仲又不難，管仲不死其君而歸桓公，鮑叔輕官讓能而任之，桓公得管仲又不難明矣。已得管仲之後，奚遽易哉！管仲非周公旦，周公旦假為天子七年，成王壯，授之以政，非為天下計也，為其職也。夫不奪子而行天下者，必不背死君而事其讎，背死君而事其讎者，必不難奪子而行天下，不難奪子而行天下者，必不難奪其君國矣。管仲，公子糾之臣也，謀殺桓公而不能，其君死而臣桓公，管仲之取捨非周公旦未可知也。若使管仲大賢也，且為湯、武，湯、武，桀、紂之臣也，桀、紂作亂，湯、武奪之，今桓公以易居其上，是以桀、紂之行居湯、武之上，桓公危矣。若使管仲不肖人也，且為田常，田常，簡公之臣也，而弒其君，今桓公以易居其上，是以簡公之易居田常之上也，桓公又危矣。管仲非周公旦以明矣，然為湯、武與田常未可知也，為湯、武有桀、紂之危，為田常有簡公之亂也。已得仲父之後，桓公奚遽易哉！若使桓公之任管仲必知不欺己也，是知不欺主之臣也；然雖知不欺主之臣，今桓公以任管仲之專借豎刁、易牙，蟲流出屍而不葬，桓公不知臣欺主與不欺主已明矣，而任臣如彼其專也，故曰：桓公闇主。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-10_s-1\",\n        \"han-fei-zi_ch-19_p-10_s-2\",\n        \"han-fei-zi_ch-19_p-10_s-3\",\n        \"han-fei-zi_ch-19_p-10_s-4\",\n        \"han-fei-zi_ch-19_p-10_s-5\",\n        \"han-fei-zi_ch-19_p-10_s-6\",\n        \"han-fei-zi_ch-19_p-10_s-7\",\n        \"han-fei-zi_ch-19_p-10_s-8\",\n        \"han-fei-zi_ch-19_p-10_s-9\",\n        \"han-fei-zi_ch-19_p-10_s-10\",\n        \"han-fei-zi_ch-19_p-10_s-11\",\n        \"han-fei-zi_ch-19_p-10_s-12\",\n        \"han-fei-zi_ch-19_p-10_s-13\",\n        \"han-fei-zi_ch-19_p-10_s-14\",\n        \"han-fei-zi_ch-19_p-10_s-15\",\n        \"han-fei-zi_ch-19_p-10_s-16\",\n        \"han-fei-zi_ch-19_p-10_s-17\",\n        \"han-fei-zi_ch-19_p-10_s-18\",\n        \"han-fei-zi_ch-19_p-10_s-19\",\n        \"han-fei-zi_ch-19_p-10_s-20\",\n        \"han-fei-zi_ch-19_p-10_s-21\",\n        \"han-fei-zi_ch-19_p-10_s-22\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：桓公的所應優，絕不是國君人的人或事的言啊。桓公以國君人為勞於索人，何索人為勞哉？伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱啊，宰所羞啊，蒙羞辱而且接國君上，賢的人或事的憂世急啊；然則國君人的人或事無道賢而且已矣，索賢不為人主難。且官職所以任賢啊，爵祿所以賞賜功啊，設官職，陳爵祿，而且士自至，國君人的人或事奚他的勞哉！使人又絕不是所佚啊，人主雖使人必以度量準的，以刑名參的，以事；遇於法規法令則行，不遇於法規法令則止；功當他的言則賞賜，不當則誅；以刑名收臣屬，以度量準下；此不可釋啊，國君人的人或事焉佚哉？索人不勞，使人不佚，而且桓公說道：勞於索人，佚於使人的人或事，不然。且桓公得管仲又不難，管仲不死他的國君而且歸桓公，鮑叔輕官讓能而且任的，桓公得管仲又不難明矣。已得管仲的後，奚遽易哉！管仲絕不是周公旦，周公旦假為天子七年，成王壯，授的以政，絕不是為天下計啊，為他的職啊。夫不奪子而且行天下的人或事，必不背死國君而且事他的讎，背死國君而且事他的讎的人或事，必不難奪子而且行天下，不難奪子而且行天下的人或事，必不難奪他的國君國矣。管仲，公子糾的臣屬啊，謀殺桓公而且不能，他的國君死而且臣屬桓公，管仲的取捨絕不是周公旦未可知啊。若使管仲大賢啊，且為湯、武，湯、武，桀、紂的臣屬啊，桀、紂作亂，湯、武奪的，今桓公以易居他的上，是以桀、紂的行居湯、武的上，桓公危矣。若使管仲不肖人啊，且為田常，田常，簡公的臣屬啊，而且弒他的國君，今桓公以易居他的上，是以簡公的易居田常的上啊，桓公又危矣。管仲絕不是周公旦以明矣，然為湯、武與田常未可知啊，為湯、武有桀、紂的危，為田常有簡公的亂啊。已得仲父的後，桓公奚遽易哉！若使桓公的任管仲必知不欺己啊，是知不欺主的臣屬啊；然雖知不欺主的臣屬，今桓公以任管仲的專借豎刁、易牙，蟲流出屍而且不葬，桓公不知臣屬欺主與不欺主已明矣，而且任臣屬如彼他的專啊，因此韓絕不是子評論說道：桓公闇主。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：桓公之所應優，非君人者之言也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰桓公之所應優非君人者之言也桓公以君人為勞於索」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「桓公以君人為勞於索人，何索人為勞哉」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 11,\n      \"canonicalText\": \"李兌治中山，苦陘令上計而入多。李兌曰：「語言辨，聽之說，不度於義，謂之窕言。無山林澤谷之利而入多者，謂之窕貨。君子不聽窕言，不受窕貨，子姑免矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-11_s-1\",\n        \"han-fei-zi_ch-19_p-11_s-2\",\n        \"han-fei-zi_ch-19_p-11_s-3\",\n        \"han-fei-zi_ch-19_p-11_s-4\",\n        \"han-fei-zi_ch-19_p-11_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"李兌治中山，苦陘令上計而且入多。李兌說道：語言辨，聽的說，不度於義，謂的窕言。無山林澤谷的利而且入多的人或事，謂的窕貨。國君子不聽窕言，不受窕貨，子姑免矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「李兌治中山，苦陘令上計而入多」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「李」、「兌」、「治」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「李兌治中山苦陘令上計而入多李兌曰語言辨聽之說不度」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「李兌曰：「語言辨，聽之說，不度於義，謂之窕言」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 12,\n      \"canonicalText\": \"或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言。」辯、在言者，說、在聽者，言非聽者也。所謂不度於義，非謂聽者必謂所聽也。聽者非小人則君子也，小人無義必不能度之義也，君子度之義必不肯說也。夫曰「言語辨，聽之說，不度於義」者，必不誠之言也。入多之為窕貨也，未可遠行也。李子之姦弗蚤禁，使至於計，是遂過也。無術以知而入多，入多者，穰也，雖倍入將奈何！舉事慎陰陽之和，種樹節四時之適，無早晚之失，寒溫之災，則入多。不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。務於畜養之理，察於土地之宜，六畜遂，五穀殖，則入多。明於權計，審於地形、舟車機械之利，用力少致功大，則入多。利商市關梁之行，能以所有致所無，客商歸之，外貨留之，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。入多、皆人為也。若天事、風雨時，寒溫適，土地不加大，而有豐年之功，則入多。人事、天功，二物者皆入多，非山林澤谷之利也。夫無山林澤谷之利入多，因謂之窕貨者，無術之言也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-12_s-1\",\n        \"han-fei-zi_ch-19_p-12_s-2\",\n        \"han-fei-zi_ch-19_p-12_s-3\",\n        \"han-fei-zi_ch-19_p-12_s-4\",\n        \"han-fei-zi_ch-19_p-12_s-5\",\n        \"han-fei-zi_ch-19_p-12_s-6\",\n        \"han-fei-zi_ch-19_p-12_s-7\",\n        \"han-fei-zi_ch-19_p-12_s-8\",\n        \"han-fei-zi_ch-19_p-12_s-9\",\n        \"han-fei-zi_ch-19_p-12_s-10\",\n        \"han-fei-zi_ch-19_p-12_s-11\",\n        \"han-fei-zi_ch-19_p-12_s-12\",\n        \"han-fei-zi_ch-19_p-12_s-13\",\n        \"han-fei-zi_ch-19_p-12_s-14\",\n        \"han-fei-zi_ch-19_p-12_s-15\",\n        \"han-fei-zi_ch-19_p-12_s-16\",\n        \"han-fei-zi_ch-19_p-12_s-17\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：李子設辭說道：夫言語辨，聽的說，不度於義的人或事，謂的窕言。辯、在言的人或事，說、在聽的人或事，言絕不是聽的人或事啊。所謂不度於義，絕不是謂聽的人或事必謂所聽啊。聽的人或事絕不是小人則國君子啊，小人無義必不能度的義啊，國君子度的義必不肯說啊。夫說道：言語辨，聽的說，不度於義的人或事，必不誠的言啊。入多的為窕貨啊，未可遠行啊。李子的姦弗蚤禁，使至於計，是遂過啊。無督察權術以知而且入多，入多的人或事，穰啊，雖倍入將奈何！舉事慎陰陽的和，種樹節四時的適，無早晚的失，寒溫的災，則入多。不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。務於畜養的理，察於土地的宜，六畜遂，五穀殖，則入多。明於權計，審於地形、舟車機械的利，用力少致功大，則入多。利商市關梁的行，能以所有致所無，客商歸的，外貨留的，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。入多、皆人為啊。若天事、風雨時，寒溫適，土地不加大，而且有豐年的功，則入多。人事、天功，二物的人或事皆入多，絕不是山林澤谷的利啊。夫無山林澤谷的利入多，因謂的窕貨的人或事，無督察權術的言啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「李」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰李子設辭曰夫言語辨聽之說不度於義者謂之窕言辯」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」辯、在言者，說、在聽者，言非聽者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 13,\n      \"canonicalText\": \"趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎！吾之士數弊也。」行人燭過免冑而對曰：「臣聞之，亦有君之不能耳，士無弊者。昔者吾先君獻公並國十七，服國三十八，戰十有二勝，是民之用也。獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人之用也。惠公沒，文公授之，圍衛、取鄴，城濮之戰，五敗荊人，取尊名於天下，亦此人之用也。亦有君不能耳，士無弊也。」簡子乃去楯、櫓立矢石之所及，鼓之而士乘之，戰大勝。簡子曰：「與吾得革車千乘，不如聞行人燭過之一言也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-13_s-1\",\n        \"han-fei-zi_ch-19_p-13_s-2\",\n        \"han-fei-zi_ch-19_p-13_s-3\",\n        \"han-fei-zi_ch-19_p-13_s-4\",\n        \"han-fei-zi_ch-19_p-13_s-5\",\n        \"han-fei-zi_ch-19_p-13_s-6\",\n        \"han-fei-zi_ch-19_p-13_s-7\",\n        \"han-fei-zi_ch-19_p-13_s-8\",\n        \"han-fei-zi_ch-19_p-13_s-9\",\n        \"han-fei-zi_ch-19_p-13_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙簡子圍衛的郛郭，犀楯、犀櫓立於矢石的所不及，鼓的而且士不起，簡子投枹說道：烏乎！吾的士數弊啊。行人燭過免冑而且對說道：臣屬聞的，亦有國君的不能耳，士無弊的人或事。昔的人或事吾先國君獻公並國十七，服國三十八，戰十有二勝，是民的用啊。獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人的用啊。惠公沒，文公授的，圍衛、取鄴，城濮的戰，五敗荊人，取尊名於天下，亦此人的用啊。亦有國君不能耳，士無弊啊。簡子乃去楯、櫓立矢石的所及，鼓的而且士乘的，戰大勝。簡子說道：與吾得革車千乘，不如聞行人燭過的一言啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「趙」、「簡」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「趙簡子圍衛之郛郭犀楯犀櫓立於矢石之所不及鼓之而士」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「吾之士數弊也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"order\": 14,\n      \"canonicalText\": \"或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也；簡子未可以速去楯、櫓也。嚴親在圍，輕犯矢石，孝子之所愛親也。孝子愛親，百數之一也。今以為身處危而人尚可戰，是以百族之子於上皆若孝子之愛親也，是行人之誣也。好利惡害，夫人之所有也。賞厚而信，人輕敵矣；刑重而必，失人不北矣。長行徇上，數百不一失。喜利畏罪，人莫不然。將眾者不出乎莫不然之數，而道乎百無一人之行，行人未知用眾之道也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-19_p-14_s-1\",\n        \"han-fei-zi_ch-19_p-14_s-2\",\n        \"han-fei-zi_ch-19_p-14_s-3\",\n        \"han-fei-zi_ch-19_p-14_s-4\",\n        \"han-fei-zi_ch-19_p-14_s-5\",\n        \"han-fei-zi_ch-19_p-14_s-6\",\n        \"han-fei-zi_ch-19_p-14_s-7\",\n        \"han-fei-zi_ch-19_p-14_s-8\",\n        \"han-fei-zi_ch-19_p-14_s-9\",\n        \"han-fei-zi_ch-19_p-14_s-10\",\n        \"han-fei-zi_ch-19_p-14_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：行人未有以說啊，乃道惠公以此人是敗，文公以此人是霸，未見所以用人啊；簡子未可以速去楯、櫓啊。嚴親在圍，輕犯矢石，孝子的所愛親啊。孝子愛親，百數的一啊。今以為身處危而且人尚可戰，是以百族的子於上皆若孝子的愛親啊，是行人的誣啊。好利惡害，夫人的所有啊。賞賜厚而且信，人輕敵矣；刑重而且必，失人不北矣。長行徇上，數百不一失。喜利畏罪，人莫不然。將眾的人或事不出乎莫不然的數，而且道乎百無一人的行，行人未知用眾的道啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難二〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「行」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰行人未有以說也乃道惠公以此人是敗文公以此人是」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「簡子未可以速去楯、櫓也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"景公過晏子曰：「子宮小，近市，請徙子家豫章之圃。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"」晏子再拜而辭曰：「且嬰家貧，待市食，而朝暮趨之，不可以遠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"」景公笑曰：「子家習市，識貴賤乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"」是時景公繁於刑，晏子對曰：「踴貴而屨賤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"」景公曰：「何故？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"」對曰：「刑多也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"」景公造然變色曰：「寡人其暴乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"」於是損刑五。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"夫刑當無多，不當無少，無以不當聞，而以太多說，無術之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"敗軍之誅以千百數，猶北不止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"即治亂之刑如恐不勝，而姦尚不盡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"今晏子不察其當否，而以太多為說，不亦妄乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"夫惜草茅者耗禾穗，惠盜賊者傷良民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"今緩刑罰，行寬惠，是利姦邪而害善人也，此非所以為治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"齊桓公飲酒醉，遺其冠，恥之，三日不朝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"管仲曰：「此非有國之恥也，公胡其不雪之以政？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「胡其善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"」因發倉囷，賜貧窮；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"論囹圄，出薄惱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"處三日而民歌之曰：「公胡不復遺冠乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"使桓公發倉囷而賜貧窮，論囹圄而出薄惱，非義也，不可以雪恥使之而義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"桓公宿義，須遺冠而後行之，則是桓公行義，非為遺冠也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"是雖雪遺冠之恥於小人，而亦遺義之恥於君子矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"且夫發囷倉而賜貧窮者，是賞無功也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"論囹圄而出薄惱者，是不誅過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"夫賞無功則民偷幸而望於上，不誅過則民不懲而易為非，此亂之本也，安可以雪恥哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"仲尼聞之曰：「仁哉文王！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"輕千里之國而請解炮烙之刑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"智哉文王！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"出千里之地而得天下之心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：仲尼以文王為智也，不亦過乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"夫智者知禍難之地而闢之者也，是以身不及於患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"使文王所以見惡於紂者，以其不得人心耶？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"則雖索人心以解惡可也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"紂以其大得人心而惡之，己又輕地以收人心，是重見疑也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"固其所以桎梏囚於羑里也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"鄭長者有言：「體道，無為、無見也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"」此最宜於文王矣，不使人疑之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"仲尼以文王為智，未及此論也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"君之力也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"」叔向對曰：「管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，君舉而服之，亦臣之力也，君何力之有？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"」師曠伏琴而笑之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"公曰：「太師奚笑也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"」師曠對曰：「臣笑叔向之對君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"凡為人臣者，猶炮宰和五味而進之君，君弗食，孰敢強之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"臣請譬之：君者、壤地也，臣者、草木也，必壤地美然後草木碩大，亦君之力也，臣何力之有？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-7_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：叔向、師曠之對皆偏辭也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"夫一匡天下，九合諸侯，美之大者也，非專君之力也，又非專臣之力也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"昔者宮之奇在虞，僖負眾在曹，二臣之智，言中事，發中功，虞、曹俱亡者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"此有其臣而無其君者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"且蹇叔處幹而幹亡，處秦而秦霸，非蹇叔愚於幹而智於秦也，此有君與無臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"向曰「臣之力也」不然矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"昔者桓公宮中二市，婦閭二百，被髮而御婦人，得管仲為五伯長，失管仲得豎刁，而身死，蟲流出屍不葬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"以為非臣之力也，且不以管仲為霸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"以為君之力也，且不以豎刁為亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"昔者晉文公慕於齊女而亡歸，咎犯極諫，故使反晉國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"故桓公以管仲合，文公以舅犯霸，而師曠曰「君之力也」又不然矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"凡五霸所以能成功名於天下者，必君臣俱有力焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-8_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"故曰：叔向、師曠之對皆偏辭也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"而優笑曰：「易哉為君，一曰仲父，二曰仲父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"」桓公曰：「吾聞君人者勞於索人，佚於使人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"吾得仲父已難矣，得仲父之後，何為不易乎哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：桓公之所應優，非君人者之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"桓公以君人為勞於索人，何索人為勞哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱也，宰所羞也，蒙羞辱而接君上，賢者之憂世急也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"然則君人者無道賢而已矣，索賢不為人主難。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"且官職所以任賢也，爵祿所以賞功也，設官職，陳爵祿，而士自至，君人者奚其勞哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"使人又非所佚也，人主雖使人必以度量準之，以刑名參之，以事；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"遇於法則行，不遇於法則止；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"功當其言則賞，不當則誅；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"以刑名收臣，以度量準下；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"此不可釋也，君人者焉佚哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"索人不勞，使人不佚，而桓公曰「勞於索人，佚於使人」者，不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"且桓公得管仲又不難，管仲不死其君而歸桓公，鮑叔輕官讓能而任之，桓公得管仲又不難明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 13,\n      \"canonicalText\": \"已得管仲之後，奚遽易哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 14,\n      \"canonicalText\": \"管仲非周公旦，周公旦假為天子七年，成王壯，授之以政，非為天下計也，為其職也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 15,\n      \"canonicalText\": \"夫不奪子而行天下者，必不背死君而事其讎，背死君而事其讎者，必不難奪子而行天下，不難奪子而行天下者，必不難奪其君國矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 16,\n      \"canonicalText\": \"管仲，公子糾之臣也，謀殺桓公而不能，其君死而臣桓公，管仲之取捨非周公旦未可知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 17,\n      \"canonicalText\": \"若使管仲大賢也，且為湯、武，湯、武，桀、紂之臣也，桀、紂作亂，湯、武奪之，今桓公以易居其上，是以桀、紂之行居湯、武之上，桓公危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 18,\n      \"canonicalText\": \"若使管仲不肖人也，且為田常，田常，簡公之臣也，而弒其君，今桓公以易居其上，是以簡公之易居田常之上也，桓公又危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 19,\n      \"canonicalText\": \"管仲非周公旦以明矣，然為湯、武與田常未可知也，為湯、武有桀、紂之危，為田常有簡公之亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 20,\n      \"canonicalText\": \"已得仲父之後，桓公奚遽易哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 21,\n      \"canonicalText\": \"若使桓公之任管仲必知不欺己也，是知不欺主之臣也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-10_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-10\",\n      \"order\": 22,\n      \"canonicalText\": \"然雖知不欺主之臣，今桓公以任管仲之專借豎刁、易牙，蟲流出屍而不葬，桓公不知臣欺主與不欺主已明矣，而任臣如彼其專也，故曰：桓公闇主。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"李兌治中山，苦陘令上計而入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"李兌曰：「語言辨，聽之說，不度於義，謂之窕言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"無山林澤谷之利而入多者，謂之窕貨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"君子不聽窕言，不受窕貨，子姑免矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"」辯、在言者，說、在聽者，言非聽者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"所謂不度於義，非謂聽者必謂所聽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"聽者非小人則君子也，小人無義必不能度之義也，君子度之義必不肯說也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"夫曰「言語辨，聽之說，不度於義」者，必不誠之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"入多之為窕貨也，未可遠行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"李子之姦弗蚤禁，使至於計，是遂過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"無術以知而入多，入多者，穰也，雖倍入將奈何！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"舉事慎陰陽之和，種樹節四時之適，無早晚之失，寒溫之災，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"務於畜養之理，察於土地之宜，六畜遂，五穀殖，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"明於權計，審於地形、舟車機械之利，用力少致功大，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 13,\n      \"canonicalText\": \"利商市關梁之行，能以所有致所無，客商歸之，外貨留之，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 14,\n      \"canonicalText\": \"入多、皆人為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 15,\n      \"canonicalText\": \"若天事、風雨時，寒溫適，土地不加大，而有豐年之功，則入多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 16,\n      \"canonicalText\": \"人事、天功，二物者皆入多，非山林澤谷之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-12_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-12\",\n      \"order\": 17,\n      \"canonicalText\": \"夫無山林澤谷之利入多，因謂之窕貨者，無術之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"吾之士數弊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"」行人燭過免冑而對曰：「臣聞之，亦有君之不能耳，士無弊者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"昔者吾先君獻公並國十七，服國三十八，戰十有二勝，是民之用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人之用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"惠公沒，文公授之，圍衛、取鄴，城濮之戰，五敗荊人，取尊名於天下，亦此人之用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"亦有君不能耳，士無弊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"」簡子乃去楯、櫓立矢石之所及，鼓之而士乘之，戰大勝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 9,\n      \"canonicalText\": \"簡子曰：「與吾得革車千乘，不如聞行人燭過之一言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-13_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-13\",\n      \"order\": 10,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"簡子未可以速去楯、櫓也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"嚴親在圍，輕犯矢石，孝子之所愛親也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"孝子愛親，百數之一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"今以為身處危而人尚可戰，是以百族之子於上皆若孝子之愛親也，是行人之誣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"好利惡害，夫人之所有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"賞厚而信，人輕敵矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"刑重而必，失人不北矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"長行徇上，數百不一失。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 10,\n      \"canonicalText\": \"喜利畏罪，人莫不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-19_p-14_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-19\",\n      \"passageId\": \"han-fei-zi_ch-19_p-14\",\n      \"order\": 11,\n      \"canonicalText\": \"將眾者不出乎莫不然之數，而道乎百無一人之行，行人未知用眾之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
